import { useCallback, useEffect, useRef, useState } from "react";
import { dashboardURL, duration, relativeTime, testsPageLink, widgetPreferences, type WidgetData, type WidgetDay, type WidgetHostProps, type WidgetOptions, type WidgetPreferences } from "./dashboard";

const css = `
.tests-widget{container:tests-widget/inline-size;display:flex;flex-direction:column;height:100%;min-height:320px;min-width:0;overflow:hidden;border:1px solid var(--color-border,#dde3ed);border-radius:12px;background:var(--color-bg-card,#fff);color:var(--color-text,#172033);font-family:inherit;font-size:12px;box-sizing:border-box}
.tests-widget *{box-sizing:border-box}.tests-widget a{color:inherit;text-decoration:none}.tests-widget button,.tests-widget select{font:inherit;color:inherit}.tw-header{display:flex;align-items:center;gap:10px;padding:16px 16px 12px}.tw-icon{display:grid;place-items:center;width:30px;height:30px;border-radius:9px;color:var(--color-accent,#5e6ad2);background:color-mix(in srgb,var(--color-accent,#5e6ad2) 12%,transparent);flex-shrink:0}.tw-heading{min-width:0;flex:1}.tw-heading h2{font-size:13px;font-weight:650;letter-spacing:-.01em;margin:0}.tw-subtitle,.tw-muted{color:var(--color-text-dim,#64748b)}.tw-subtitle{margin:3px 0 0;font-size:11px}.tw-open{font-size:11px;white-space:nowrap;color:var(--color-text-muted,#536179)!important}.tw-open:hover,.tw-row:hover .tw-name{color:var(--color-accent,#5e6ad2)!important}.tw-filters{display:flex;gap:6px;flex-wrap:wrap;padding:0 16px 12px;border-bottom:1px solid var(--color-border,#dde3ed)}.tw-filters select{min-width:0;max-width:100%;flex:1 1 90px;border:1px solid var(--color-border,#dde3ed);border-radius:6px;padding:5px 22px 5px 7px;background:var(--color-bg-input,#f7f8fb);font-size:11px}.tests-widget :focus-visible{outline:2px solid var(--color-accent,#5e6ad2);outline-offset:2px}.tw-stats{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px 12px;padding:16px}.tw-stat span{display:block;font-size:10px;color:var(--color-text-dim,#64748b)}.tw-stat strong{display:block;font-size:25px;font-weight:650;letter-spacing:-.04em;font-variant-numeric:tabular-nums;line-height:1.25;margin-top:3px}.tw-stat small{font-size:10px;color:var(--color-text-dim,#64748b)}.tw-danger{color:var(--color-red,#b91c1c)}.tw-list{min-height:0;overflow:auto;flex:1}.tw-list-title{display:flex;align-items:center;justify-content:space-between;padding:4px 16px 8px;font-size:10px;font-weight:600;color:var(--color-text-dim,#64748b);text-transform:uppercase;letter-spacing:.06em}.tw-row{display:block;padding:12px 16px;border-top:1px solid var(--color-border,#dde3ed)}.tw-row:hover{background:var(--color-bg-hover,#f7f8fb)}.tw-line{display:flex;align-items:center;gap:8px;min-width:0}.tw-name{font-size:12px;font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;min-width:0;flex:1}.tw-time{font-size:10px;white-space:nowrap;color:var(--color-text-dim,#64748b)}.tw-meta{display:flex;align-items:center;gap:7px;flex-wrap:wrap;margin-top:6px;font-size:10px;color:var(--color-text-dim,#64748b)}.tw-env{font-size:10px;border:1px solid var(--color-border,#dde3ed);padding:1px 5px;border-radius:4px;max-width:100%;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.tw-status{display:inline-flex;align-items:center;gap:4px;border-radius:5px;padding:2px 6px;font-size:10px;font-weight:600;white-space:nowrap;background:color-mix(in srgb,currentColor 10%,transparent);color:var(--color-text-muted,#536179)}.tw-status:before{content:"";width:5px;height:5px;border-radius:50%;background:currentColor}.tw-status.passed{color:var(--color-green,#15803d)}.tw-status.failed,.tw-status.error{color:var(--color-red,#b91c1c)}.tw-status.running{color:var(--color-accent,#5e6ad2)}.tw-status.cancelled,.tw-status.cancelling{color:var(--color-yellow,#9a6700)}.tw-state{display:flex;flex:1;min-height:140px;align-items:flex-start;justify-content:center;flex-direction:column;padding:20px 16px;gap:7px}.tw-state strong{font-size:12px}.tw-state p{font-size:11px;margin:0;line-height:1.5;color:var(--color-text-dim,#64748b)}.tw-state a,.tw-state button{color:var(--color-accent,#5e6ad2);font-size:11px}.tw-state button{border:1px solid var(--color-border,#dde3ed);border-radius:5px;padding:5px 9px;background:transparent;cursor:pointer}.tw-footer{display:flex;gap:8px;justify-content:space-between;flex-wrap:wrap;flex-shrink:0;padding:10px 16px;border-top:1px solid var(--color-border,#dde3ed);font-size:10px;color:var(--color-text-dim,#64748b)}.tw-message{font-size:11px;line-height:1.5;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;margin:7px 0;color:var(--color-text-muted,#536179);overflow-wrap:anywhere}.tw-error-name{font-size:10px;color:var(--color-text-dim,#64748b);margin:5px 0 0}.tw-count{font-size:10px;padding:2px 6px;border-radius:5px;background:var(--color-bg-input,#f7f8fb);color:var(--color-text-muted,#536179);white-space:nowrap}.tw-chart{padding:0 16px 12px;margin:0}.tw-chart svg{display:block;width:100%;height:68px;overflow:visible}.tw-chart figcaption{display:flex;align-items:center;justify-content:space-between;font-size:10px;color:var(--color-text-dim,#64748b);margin-bottom:8px}.tw-legend{display:flex;gap:9px}.tw-legend i{display:inline-block;width:5px;height:5px;border-radius:50%;margin-right:3px}.tw-days{display:flex;justify-content:space-around;font-size:9px;color:var(--color-text-dim,#64748b);margin-top:4px}.tw-more{display:block;text-align:center;font-size:11px;padding:10px 16px;border-top:1px solid var(--color-border,#dde3ed);color:var(--color-accent,#5e6ad2)!important}
@container tests-widget (min-width:540px){.tw-stats{grid-template-columns:repeat(4,minmax(0,1fr))}.tw-header{padding-top:18px}.tw-row{padding-top:13px;padding-bottom:13px}}
`;
const titles = { overview: "Tests overview", failures: "Recent failures" };
const int = (n: number) => n.toLocaleString();
const statusLabel = (s: string) => s.charAt(0).toUpperCase() + s.slice(1);
function Status({ value }: { value: string }) { return <span className={`tw-status ${value}`}>{statusLabel(value)}</span>; }
function Icon({ failure }: { failure: boolean }) { return <span className="tw-icon"><svg aria-hidden="true" width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.7" strokeLinecap="round" strokeLinejoin="round">{failure ? <><path d="m12 3 10 18H2L12 3Z" /><path d="M12 9v4m0 4h.01" /></> : <><path d="M9 3h6m-5 0v6l-6 10a1.3 1.3 0 0 0 1 2h14a1.3 1.3 0 0 0 1-2L14 9V3M8 14h8" /></>}</svg></span>; }
function Trend({ days }: { days: WidgetDay[] }) {
  const max = Math.max(1, ...days.map(d => d.runs)), width = 320, slot = width / days.length;
  const colors = ["var(--color-green,#15803d)", "var(--color-red,#b91c1c)", "var(--color-yellow,#9a6700)", "var(--color-border,#cbd5e1)"];
  return <figure className="tw-chart"><figcaption><span>Daily runs · UTC</span><span className="tw-legend"><span><i style={{ background: colors[0] }} />Passed</span><span><i style={{ background: colors[1] }} />Failed</span></span></figcaption>
    <svg role="img" aria-label="Daily test runs by status" viewBox={`0 0 ${width} 68`} preserveAspectRatio="none">{days.map((d, i) => {
      let y = 64; return <g key={d.date}><title>{`${d.date}: ${d.runs} runs, ${d.passed} passed, ${d.failed} failed, ${d.cancelled} cancelled`}</title>{[d.passed, d.failed, d.cancelled, d.runs - d.passed - d.failed - d.cancelled].map((n, k) => { const height = n / max * 60; y -= height; return <rect key={k} x={i * slot + slot * .2} y={y} width={slot * .6} height={height} rx="2" fill={colors[k]} />; })}</g>;
    })}</svg><div className="tw-days">{days.map(d => <span key={d.date}>{new Intl.DateTimeFormat(undefined, { day: "numeric", month: "short", timeZone: "UTC" }).format(new Date(d.date + "T00:00:00Z"))}</span>)}</div>
  </figure>;
}
export function TestsDashboardWidget(props: WidgetHostProps & { kind: "overview" | "failures" }) {
  const settings = widgetPreferences(props.widgetSettings);
  return <Widget key={`${props.projectId}:${props.installId}:${props.widgetId}:${JSON.stringify(settings)}`} {...props} initial={settings} />;
}
function Widget(props: WidgetHostProps & { kind: "overview" | "failures"; initial: WidgetPreferences }) {
  const [filters, setFilters] = useState(props.initial), [data, setData] = useState<WidgetData | null>(null);
  const [options, setOptions] = useState<WidgetOptions>({ suites: [], environments: [] }), [error, setError] = useState("");
  const request = useRef<AbortController | null>(null);
  const url = dashboardURL(props, props.kind, filters), title = titles[props.kind];
  const load = useCallback(async () => {
    if (!props.projectId) return;
    request.current?.abort(); const controller = new AbortController(); request.current = controller;
    try {
      const response = await fetch(url, { credentials: "same-origin", signal: controller.signal });
      if (!response.ok) throw new Error("Test results could not be loaded. Try again.");
      const value = await response.json() as WidgetData;
      if (controller.signal.aborted || request.current !== controller) return;
      setData(value); setOptions(value.options); setError("");
    } catch (e) { if (!controller.signal.aborted && request.current === controller) setError((e as Error).message); }
  }, [url, props.projectId]);
  useEffect(() => { setData(null); setError(""); }, [load]);
  useEffect(() => { void load(); return () => request.current?.abort(); }, [load, props.eventRevision]);
  useEffect(() => { const timer = window.setInterval(() => void load(), 30000); const focus = () => void load(); window.addEventListener("focus", focus); return () => { window.clearInterval(timer); window.removeEventListener("focus", focus); }; }, [load]);
  const filter = (key: keyof WidgetPreferences, value: string | number | boolean) => setFilters(old => ({ ...old, [key]: value }));
  const environments = filters.environment && !options.environments.includes(filters.environment) ? [filters.environment, ...options.environments] : options.environments;
  return <section className="tests-widget" aria-label={title}>
    <style>{css}</style><header className="tw-header"><Icon failure={props.kind === "failures"} /><div className="tw-heading"><h2>{title}</h2><p className="tw-subtitle">{props.kind === "overview" ? "Latest runs and testing health" : "Failed checks and saved evidence"}</p></div><a className="tw-open" href={testsPageLink(props)}>Open Tests ↗</a></header>
    {!props.projectId ? <div className="tw-state"><strong>Select a project</strong><p>Choose a project to see its test results.</p></div> : <>
      <div className="tw-filters"><select aria-label="Suite" value={filters.suite} onChange={e => filter("suite", Number(e.target.value))}><option value={0}>All suites</option>{options.suites.map(s => <option key={s.id} value={s.id}>{s.name}{s.archived ? " (archived)" : ""}</option>)}</select>
        <select aria-label="Environment" value={filters.environment} onChange={e => filter("environment", e.target.value)}><option value="">All environments</option>{environments.map(e => <option key={e} value={e}>{e}</option>)}</select>
        <select aria-label="Time window" value={filters.hours} onChange={e => filter("hours", Number(e.target.value))}><option value={24}>Last 24 hours</option><option value={168}>Last 7 days</option></select>
        {props.kind === "failures" && <select aria-label="Failure grouping" value={String(filters.group)} onChange={e => filter("group", e.target.value === "true")}><option value="true">Group repeated</option><option value="false">Every failure</option></select>}
      </div>
      {error ? <div className="tw-state" role="alert"><strong>Results unavailable</strong><p>{error}</p><button onClick={() => void load()}>Retry</button></div> : !data ? <div className="tw-state" role="status"><p>Loading test results…</p></div> : props.kind === "overview" && data.stats ? <>
        <div className="tw-stats"><div className="tw-stat"><span>Runs</span><strong>{int(data.stats.runs)}</strong><small>{filters.hours === 24 ? "past 24 hours" : "past 7 days"}</small></div>
          <div className="tw-stat"><span>Pass rate</span><strong>{data.stats.pass_rate === null ? "—" : `${Math.round(data.stats.pass_rate)}%`}</strong><small>{data.stats.pass_rate === null ? "no completed results" : `${int(data.stats.passed)} of ${int(data.stats.passed + data.stats.failed)} completed`}</small></div>
          <div className="tw-stat"><span>Failed runs</span><strong className={data.stats.failed ? "tw-danger" : ""}>{int(data.stats.failed)}</strong><small>cancelled runs excluded</small></div>
          <div className="tw-stat"><span>Active now</span><strong>{int(data.stats.running + data.stats.queued)}</strong><small>{data.stats.running} running · {data.stats.queued} queued</small></div></div>
        {props.widgetSize === "full" && (data.trend?.length || 0) > 0 && data.stats.runs > 0 && <Trend days={data.trend!} />}
        {!data.recent?.length ? <div className="tw-state"><strong>{options.suites.length ? "No runs in this period" : "No tests run yet"}</strong><p>{options.suites.length ? "Try another time window or filter, or open Tests to run a suite." : "Create a suite in Tests to start collecting results."}</p><a href={testsPageLink(props)}>Open Tests →</a></div> : <div className="tw-list" aria-live="polite"><div className="tw-list-title">Latest results <span>{data.recent.length} recent runs</span></div>{data.recent.map(r => <a className="tw-row" key={r.id} href={testsPageLink(props, r)} aria-label={`Open run ${r.id}: ${r.suite_name}, ${statusLabel(r.status)}`}><div className="tw-line"><span className="tw-name" title={r.suite_name}>{r.suite_name}</span><Status value={r.status} /></div><div className="tw-meta"><span className="tw-env" title={r.environment}>{r.environment}</span><span>{r.passed} passed · {r.failed} failed</span>{r.duration_ms !== null && <span>{duration(r.duration_ms)}{["running", "cancelling"].includes(r.status) ? " elapsed" : ""}</span>}<span className="tw-time" title={new Date(r.created_at).toLocaleString()}>#{r.id} · {relativeTime(r.created_at)}</span></div></a>)}</div>}
        <footer className="tw-footer"><span>{data.stats.cancelled} cancelled · excluded from pass rate</span><span>Updated {relativeTime(data.as_of)}</span></footer>
      </> : <>
        {!data.failures.length ? <div className="tw-state"><strong>No failures in this period</strong><p>Failed checks will appear here with links to their saved evidence.</p></div> : <div className="tw-list" aria-live="polite">{data.failures.map(f => <a className="tw-row" key={`${f.run_id}:${f.check_id}`} href={testsPageLink(props, { id: f.run_id, suite_id: f.suite_id })} aria-label={`Open failed run ${f.run_id}: ${f.check_name}`}><div className="tw-line"><span className="tw-name" title={f.check_name}>{f.check_name}</span>{f.occurrences > 1 && <span className="tw-count">{f.occurrences} occurrences</span>}</div><p className="tw-error-name" title={f.suite_name}>{f.suite_name}{f.step_id ? ` · ${f.step_id}` : ""}</p><p className="tw-message">{f.message}</p><div className="tw-meta"><span className="tw-env">{f.environment}</span>{f.has_screenshot && <span aria-label="Screenshot available">▧ Screenshot</span>}<span className="tw-time" title={new Date(f.created_at).toLocaleString()}>#{f.run_id} · {relativeTime(f.created_at)}</span><span>View evidence →</span></div></a>)}</div>}
        {data.total > data.failures.length && <a className="tw-more" href={testsPageLink(props)}>More failures in Tests →</a>}
        <footer className="tw-footer"><span>{data.total} {filters.group ? "failure groups" : "failures"} · {filters.hours === 24 ? "past 24 hours" : "past 7 days"}</span><span>Updated {relativeTime(data.as_of)}</span></footer>
      </>}
    </>}
  </section>;
}
